import Foundation
struct Firmware: Decodable { let id: Int; let build: Int }
let payloads = [#"{"id":6}"#, #"{"id":6,"build":"12"}"#]
for json in payloads {
    do {
        _ = try JSONDecoder().decode(Firmware.self, from: Data(json.utf8))
    } catch DecodingError.keyNotFound(let field, _) {
        print("Нет ключа: \(field.stringValue)")
    } catch DecodingError.typeMismatch(_, let context) {
        let field = context.codingPath.last?.stringValue ?? "<корень>"
        print("Неверный тип: \(field)")
    } catch { print("Другая ошибка") }
}

Вывод «Нет ключа: build», затем «Неверный тип: build». keyNotFound передаёт ключ отдельно, typeMismatch — путь в context; исходные данные сохранены.

